      "@type": "Question",
      "name": "What bandwidth options are available?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Circuits are sized to the traffic profile you send us, from sub-1 Gbps access links up to 10 Gbps and above for high-capacity routes such as India to Australia."
      }
    },
