      "@type": "Question",
      "name": "Which routes do you cover?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Cross-Pacific and Asia-Pacific routes, including India to Australia and other APAC point-to-point lanes, from 20+ PoPs and IDCs. Hong Kong to Taipei, Singapore, Tokyo and Los Angeles are among the protected routes."
      }
    },
